from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    results = []
    for group in paren_string.split():
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':  
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        results.append(max_depth)
    return results

from typing import List

def filter_by_substring(strings: List[str], substring: str) -> List[str]:
    return [s for s in strings if substring in s]

from typing import List, Any

def filter_integers(values: List[Any]) -> List[int]:
    return [value for value in values if isinstance(value, int)]

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    # Start with the smallest prime factor
    factor = 2
    # Continue until all factors are checked
    while n > 1:
        if n % factor == 0:
            n //= factor  # Reduce n by dividing it by the factor
        else:
            factor += 1  # Move to the next potential factor
    return factor  # When n is reduced to 1, the largest factor remains as the last factor checked

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':  
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def vowels_count(s):
    vowels = 'aeiouAEIOU'
    count = 0
    length = len(s)
    for i, char in enumerate(s):
        if char in vowels:
            count += 1
        elif char == 'y' or char == 'Y':
            if i == length - 1:
                count += 1
    return count

