def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []
    for word in words:
        sorted_word = ''.join(sorted(c for c in word if c.isalpha()))
        result = ''
        alpha_idx = 0
        for char in word:
            if char.isalpha():
                result += sorted_word[alpha_idx]
                alpha_idx += 1
            else:
                result += char
        ordered_words.append(result)
    return ' '.join(ordered_words)

def next_smallest(lst):
    unique_elements = set(lst)
    if len(unique_elements) < 2:
        return None
    sorted_elements = sorted(unique_elements)
    return sorted_elements[1]

import math

def max_fill(grid, capacity):
    total_water = sum(sum(row) for row in grid)
    return math.ceil(total_water / capacity)

def minPath(grid, k):
    from collections import deque
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    min_path = None

    def bfs(start_row, start_col):
        queue = deque([(start_row, start_col, [grid[start_row][start_col]])])
        while queue:
            row, col, path = queue.popleft()
            if len(path) == k:
                nonlocal min_path
                if min_path is None or path < min_path:
                    min_path = path
                continue
            for dr, dc in directions:
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < N and 0 <= new_col < N:
                    queue.append((new_row, new_col, path + [grid[new_row][new_col]]))

    for i in range(N):
        for j in range(N):
            bfs(i, j)

    return min_path

def is_equal_to_sum_even(n):
    """Evaluate whether the given number n can be written as the sum of exactly 4 positive even numbers"""
    return n >= 8 and n % 2 == 0

def sum_squares(lst):
    total = 0
    for i, value in enumerate(lst):
        if i % 3 == 0:
            total += value ** 2
        elif i % 4 == 0:
            total += value ** 3
        else:
            total += value
    return total

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))
    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def x_or_y(n, x, y):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    return x if is_prime(n) else y

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
